Figure 7.1: Central London seen from the International Space Station. The Thames and major parks are easy to distinguish. Source: NASA Earth Observatory, 2 April 2005.



// Introductory London bounding-box ROI from Landsat 9
var london_bbox = ee.Geometry.Rectangle([-0.51, 51.28, 0.33, 51.69]);

var l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
  .filterDate('2025-06-01', '2025-09-01')
  .filterBounds(london_bbox)
  .map(function(img){
    var opt = img.select(['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
                 .multiply(0.0000275).add(-0.2);
    return img.addBands(opt, null, true);
  });

var composite = l9.median().clip(london_bbox);
var ndvi = composite.normalizedDifference(['SR_B5','SR_B4']);

Map.setCenter(-0.118, 51.509, 10);
Map.addLayer(composite,
  {bands:['SR_B4','SR_B3','SR_B2'], min:0, max:0.3}, 'True Colour');
Map.addLayer(ndvi,
  {min:-0.1, max:0.7, palette:['white','yellow','green','darkgreen']}, 'NDVI');









Figure 7.2: True-colour Landsat 9 composite of London, summer 2025











Figure 7.3: NDVI from the same composite. Parks like Richmond and Hampstead Heath stand out clearly in dark green.












Figure 7.4: Scale comparison: the same NIR band sampled at a single London point returns different values depending on the scale parameter. At 1000 m the value drops noticeably because nearby non-vegetation pixels get averaged in.

